from pathlib import Path
from lxml import html
from html import escape
p=Path(site_dir)
groups=[('Overview & setup',[48,45,18,19,10]),('Phone',[8,4,3,2,7,6,5]),('Smartwatch',[44,38,43,40,39,42,41]),('Researcher dashboard',[34,28,31,33,30,29,32]),('Workflows & guides',[27,21,22,23,24,25,26,1,20,35,47,9,36,37,46]),('Database',[17,16,13,12,14,11,15])]
titles={}
for f in p.glob('page-*.html'):
    d=html.parse(str(f));titles[int(f.stem[-2:])]=d.xpath('//title/text()')[0].split(' | ')[0]
header='''<a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="index.html"><span class="mark" aria-hidden="true">≈</span> Haptic Feedback <span class="brand-sub">/ Documentation</span></a><div class="top-links"><a href="page-45.html">Architecture</a><a href="page-18.html">Get started <span aria-hidden="true">↗</span></a></div></header>'''
foot='<footer><span>Haptic Feedback · Documentation</span><span>Anonymous review edition · Identifying media and credentials omitted</span></footer>'
for f in p.glob('*.html'):
    doc=html.parse(str(f));body=doc.xpath('//body')[0];main=doc.xpath('//main')[0];nav=doc.xpath('//nav')[0]
    for group,ids in groups:
        section=html.Element('section',{'class':'nav-group'});h=html.Element('h2');h.text=group;section.append(h)
        for i in ids:
            a=nav.xpath(f'./a[@href="page-{i:02}.html"]')
            if a:section.append(a[0])
        nav.append(section)
    for e in main.xpath('./footer'):e.drop_tree()
    current=int(f.stem[-2:]) if f.name!='index.html' else None
    if current:
        group=next(g for g,ids in groups if current in ids)
        crumb=html.fragment_fromstring('<div class="breadcrumb"><a href="index.html">Documentation</a><span>/</span>'+escape(group)+'</div>')
        main.insert(0,crumb)
        article=main.xpath('./article')[0];toc=html.Element('aside',{'class':'toc','aria-label':'On this page'})
        h=html.Element('h2');h.text='On this page';toc.append(h)
        for idx,e in enumerate(article.xpath('.//h1|.//h2|.//h3')):
            if idx==0:continue
            e.set('id',f'section-{idx}')
            a=html.Element('a',href=f'#section-{idx}');a.text=e.text_content();toc.append(a)
        wrapper=html.Element('div',{'class':'reading'});main.append(wrapper);wrapper.append(article);wrapper.append(toc)
        main.append(html.fragment_fromstring('<div class="page-end"><a href="index.html">← All documentation</a><a href="#main">Back to top ↑</a></div>'))
    body.clear()
    for e in html.fragments_fromstring(header):body.append(e)
    if current:
        layout=html.Element('div',{'class':'layout'});body.append(layout);layout.append(nav);layout.append(main)
    else:
        body.set('class','home')
        hero='''<main id="main" class="landing"><section class="hero"><div><div class="eyebrow"><span></span> SMARTWATCH HAPTIC FEEDBACK SYSTEM</div><h1>From sensing<br>to <em>feeling.</em></h1><p class="intro">A connected platform for exploring real-time haptic feedback. Understand the system, set up your devices, and build your study.</p><div class="actions"><a class="button" href="page-18.html">Start with installation <span>↗</span></a><a class="text-link" href="page-45.html">Explore the architecture →</a></div><div class="hero-meta">Wear OS <span>·</span> Android <span>·</span> n8n <span>·</span> PostgreSQL</div></div><div class="system-visual" aria-label="System components: smartwatch sensing and feedback, phone relay, backend workflows, and researcher dashboard"><div class="visual-top"><span>SYSTEM AT A GLANCE</span><span class="signal">● Connected components</span></div><div class="orbit"><div class="ring r1"></div><div class="ring r2"></div><div class="watch-art"><div class="watch-screen"><span>HAPTIC FEEDBACK</span><div class="wave">∿∿∿</div><small>Sense. Interpret. Respond.</small></div></div></div><div class="flow"><a href="page-44.html"><b>01</b> Watch<small>Sense & vibrate</small></a><a href="page-08.html"><b>02</b> Phone<small>Relay & connect</small></a><a href="page-27.html"><b>03</b> Backend<small>Process & respond</small></a></div><a class="dashboard-link" href="page-34.html">Researcher dashboard <span>Configure & monitor ↗</span></a></div></section><section class="browse" id="browse"><div class="section-heading"><div><div class="eyebrow">THE DOCUMENTATION</div><h2>Find your starting point.</h2></div><p>From the first connection to your next experiment.</p></div><div class="topic-grid">'''
        topics=[('01','System overview','See how sensing, communication and feedback fit together.',45,'overview'),('02','Phone & smartwatch','Connect your devices and configure sensing and vibration.',19,'devices'),('03','Researcher dashboard','Manage users, use cases, mappings and study schedules.',34,'dashboard'),('04','Backend & data','Understand workflows, database structure and credentials.',27,'backend')]
        hero+=''.join(f'<a class="topic {cls}" href="page-{i:02}.html"><span class="topic-number">{num} <span>↗</span></span><h3>{t}</h3><p>{desc}</p><span class="topic-action">Explore guides →</span></a>' for num,t,desc,i,cls in topics)
        hero+='''</div></section><section class="guide-section"><div class="guide-intro"><div class="eyebrow">EXPLORE THE GUIDES</div><h2>The details,<br>when you need them.</h2><p>Search across all 48 pages or browse by component. Setup instructions, configuration references and troubleshooting, in one place.</p><a class="text-link" href="page-48.html">Read the project overview →</a></div><div class="guide-browser"></div></section></main>'''
        landing=html.fragment_fromstring(hero);body.append(landing);landing.xpath('.//div[@class="guide-browser"]')[0].append(nav)
    body.append(html.fragment_fromstring(foot))
    f.write_text('<!doctype html>\n'+html.tostring(doc,encoding='unicode'),encoding='utf-8')
